import{_ as a,o,a as e,a3 as i}from"./chunks/framework.CkbYhqXo.js";const m=JSON.parse('{"title":"Modpacks","description":"Creating, importing and exporting modpacks in Stuzhik. Supports .stzhk, .mrpack (Modrinth) and .zip (CurseForge) formats. Syncing with friends.","frontmatter":{"description":"Creating, importing and exporting modpacks in Stuzhik. Supports .stzhk, .mrpack (Modrinth) and .zip (CurseForge) formats. Syncing with friends.","head":[["meta",{"name":"keywords","content":"minecraft modpacks, stuzhik, create minecraft modpack, export modpack, mrpack, curseforge modpack, sync mods with friends"}]]},"headers":[],"relativePath":"en/guide/modpacks.md","filePath":"en/guide/modpacks.md"}'),r={name:"en/guide/modpacks.md"};function n(l,t,s,d,h,c){return o(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="modpacks" tabindex="-1">Modpacks <a class="header-anchor" href="#modpacks" aria-label="Permalink to &quot;Modpacks&quot;">​</a></h1><h2 id="stuzhik-format-stzhk" tabindex="-1">Stuzhik format (.stzhk) <a class="header-anchor" href="#stuzhik-format-stzhk" aria-label="Permalink to &quot;Stuzhik format (.stzhk)&quot;">​</a></h2><p>Stuzhik uses its own modpack format, <code>.stzhk</code> - optimized for fast installation and maximum compatibility.</p><h3 id="advantages" tabindex="-1">Advantages <a class="header-anchor" href="#advantages" aria-label="Permalink to &quot;Advantages&quot;">​</a></h3><ul><li>Fast installation - optimized structure</li><li>Full compatibility - all settings are kept</li><li>Compact size - efficient compression</li><li>Metadata - version, author, description, screenshots</li></ul><h3 id="exporting-to-stzhk" tabindex="-1">Exporting to .stzhk <a class="header-anchor" href="#exporting-to-stzhk" aria-label="Permalink to &quot;Exporting to .stzhk&quot;">​</a></h3><ol><li>Open the instance</li><li>&quot;Export&quot; button → &quot;Stuzhik (.stzhk)&quot;</li><li>Fill in the metadata</li><li>Save the file</li></ol><h3 id="importing-stzhk" tabindex="-1">Importing .stzhk <a class="header-anchor" href="#importing-stzhk" aria-label="Permalink to &quot;Importing .stzhk&quot;">​</a></h3><p>Just drag the <code>.stzhk</code> file into the Stuzhik window, or:</p><ol><li>Home → &quot;Import&quot;</li><li>Choose the file</li><li>Done</li></ol><h2 id="compatibility-with-other-formats" tabindex="-1">Compatibility with other formats <a class="header-anchor" href="#compatibility-with-other-formats" aria-label="Permalink to &quot;Compatibility with other formats&quot;">​</a></h2><p>Stuzhik also supports importing from popular formats:</p><table tabindex="0"><thead><tr><th>Format</th><th>Source</th><th>Support</th></tr></thead><tbody><tr><td><code>.stzhk</code></td><td>Stuzhik</td><td>Full</td></tr><tr><td><code>.mrpack</code></td><td>Modrinth</td><td>Full</td></tr><tr><td><code>.zip</code></td><td>CurseForge</td><td>Full</td></tr></tbody></table><h3 id="importing-from-modrinth" tabindex="-1">Importing from Modrinth <a class="header-anchor" href="#importing-from-modrinth" aria-label="Permalink to &quot;Importing from Modrinth&quot;">​</a></h3><ol><li>Home → &quot;Modpack&quot;</li><li>Search by name</li><li>Choose a version → &quot;Install&quot;</li></ol><h3 id="importing-from-curseforge" tabindex="-1">Importing from CurseForge <a class="header-anchor" href="#importing-from-curseforge" aria-label="Permalink to &quot;Importing from CurseForge&quot;">​</a></h3><ol><li>Download the <code>.zip</code> from CurseForge</li><li>Stuzhik → &quot;Import&quot;</li><li>Choose the file</li></ol><h2 id="creating-a-modpack" tabindex="-1">Creating a modpack <a class="header-anchor" href="#creating-a-modpack" aria-label="Permalink to &quot;Creating a modpack&quot;">​</a></h2><h3 id="what-s-included" tabindex="-1">What&#39;s included <a class="header-anchor" href="#what-s-included" aria-label="Permalink to &quot;What&#39;s included&quot;">​</a></h3><ul><li>The mod list with versions</li><li>Mod configs</li><li>Game settings</li><li>Resource packs and shaders (optional)</li></ul><h3 id="what-s-not-included" tabindex="-1">What&#39;s NOT included <a class="header-anchor" href="#what-s-not-included" aria-label="Permalink to &quot;What&#39;s NOT included&quot;">​</a></h3><ul><li>Minecraft (downloaded separately)</li><li>The loader (installed automatically)</li><li>World saves</li></ul><h2 id="modpack-editor" tabindex="-1">Modpack editor <a class="header-anchor" href="#modpack-editor" aria-label="Permalink to &quot;Modpack editor&quot;">​</a></h2><h3 id="comparing-versions" tabindex="-1">Comparing versions <a class="header-anchor" href="#comparing-versions" aria-label="Permalink to &quot;Comparing versions&quot;">​</a></h3><ol><li>The &quot;Modpacks&quot; section in the sidebar → the &quot;Compare&quot; button</li><li>Pick the first and second modpack: a file, an instance, or a modpack from Modrinth/CurseForge (with the version you need)</li><li>You&#39;ll see: <ul><li>Mods only in the first and only in the second</li><li>Mods with different versions</li><li>Differences in configs and other files</li></ul></li></ol><h3 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h3><ol><li>Open the instance with the modpack</li><li>&quot;Check for updates&quot;</li><li>Apply the changes</li></ol><h2 id="server-modpacks" tabindex="-1">Server modpacks <a class="header-anchor" href="#server-modpacks" aria-label="Permalink to &quot;Server modpacks&quot;">​</a></h2><p>When exporting for a server, Stuzhik automatically:</p><ul><li>Excludes client-only mods</li><li>Adds server-only mods</li><li>Configures <code>server.properties</code></li></ul><h2 id="syncing-with-friends" tabindex="-1">Syncing with friends <a class="header-anchor" href="#syncing-with-friends" aria-label="Permalink to &quot;Syncing with friends&quot;">​</a></h2><h3 id="through-stuzhik-connect-recommended" tabindex="-1">Through Stuzhik Connect (recommended) <a class="header-anchor" href="#through-stuzhik-connect-recommended" aria-label="Permalink to &quot;Through Stuzhik Connect (recommended)&quot;">​</a></h3><p>Direct transfer with no intermediate files, and everything downloads P2P. You can&#39;t send a modpack to a friend: Connect only works by &quot;pulling&quot;. Open the modpack to friends (&quot;Sharing&quot; → &quot;Friends only&quot;), your friend takes it on their side with the &quot;Get&quot; button, and by default your launcher asks for your permission — the files start moving only when you click &quot;Allow&quot;. More in <a href="/en/guide/connect.html#transferring-modpacks">Stuzhik Connect</a>.</p><h3 id="manually" tabindex="-1">Manually <a class="header-anchor" href="#manually" aria-label="Permalink to &quot;Manually&quot;">​</a></h3><p>If Connect doesn&#39;t suit you (for example, you&#39;re sending it through a messenger or on a USB stick):</p><ol><li>Export the modpack to <code>.stzhk</code></li><li>Send it to your friends any way you like</li><li>They import the file into Stuzhik</li><li>Everyone is on the same versions</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="installation-is-stuck" tabindex="-1">Installation is stuck <a class="header-anchor" href="#installation-is-stuck" aria-label="Permalink to &quot;Installation is stuck&quot;">​</a></h3><p>Dev Console (<code>Ctrl+Shift+D</code>) shows the details. Possible causes:</p><ul><li>A slow connection</li><li>An unavailable mod</li></ul><h3 id="crash-after-installation" tabindex="-1">Crash after installation <a class="header-anchor" href="#crash-after-installation" aria-label="Permalink to &quot;Crash after installation&quot;">​</a></h3><p>Log Analyzer automatically finds the problematic mods and suggests solutions.</p>',42)])])}const p=a(r,[["render",n]]);export{m as __pageData,p as default};
